:root {
  --bg: #090b0e;
  --panel: #0e1115;
  --panel-2: #12161b;
  --panel-3: #171c22;

  --line: #20262d;
  --line-strong: #2b333c;

  --text: #f2f4f6;
  --text-2: #d0d5da;
  --muted: #8a929b;
  --muted-2: #636b74;

  --blue: #72b5ee;
  --blue-strong: #8bc5f7;
  --blue-soft: rgba(114, 181, 238, 0.09);

  --green: #63d29b;
  --red: #ef737e;
  --yellow: #dfbb74;

  --radius: 9px;
  --radius-sm: 7px;

  --shadow: 0 10px 28px rgba(0, 0, 0, 0.13);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--bg);
  color-scheme: dark;
  scrollbar-width: none;
}

html::-webkit-scrollbar,
body::-webkit-scrollbar {
  width: 0;
  height: 0;
}

body {
  margin: 0;
  min-width: 320px;

  background: linear-gradient(180deg, #090b0e 0%, #080a0d 100%);

  color: var(--text);

  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  border: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  width: calc(100% - 56px);
  margin: 0 28px;
}

.page {
  min-height: 100vh;
}

.page-content {
  padding: 30px 0 70px;
}

/* ============================================================
   PUBLIC HEADER
   ============================================================ */

.topbar,
.site-header {
  position: sticky;
  top: 0;
  z-index: 40;

  background: rgba(9, 11, 14, 0.96);

  border-bottom: 1px solid var(--line);
}

.nav,
.shell-nav {
  min-height: 66px;

  display: flex;
  align-items: center;

  gap: 22px;
}

/* marca antiga e nova */

.nav-brand,
.shell-brand {
  display: inline-flex;
  align-items: center;

  gap: 10px;

  flex: 0 0 auto;
}

.nav-logo {
  position: relative;

  width: 40px;
  height: 40px;

  border-radius: 9px;

  background: #0b1117 url("/tz-logo.svg") center / 40px 40px no-repeat;

  border: 1px solid rgba(114, 181, 238, 0.24);

  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.25);

  font-size: 0;
}

.nav-logo::before,
.nav-logo::after {
  display: none;
}

.nav-brand > span:last-child {
  font-size: 18px;
  font-weight: 850;

  letter-spacing: -0.055em;

  color: #eef2f5;
}

.public-nav {
  flex: 1;

  display: flex;
  justify-content: center;

  gap: 2px;
}

.public-nav a,
.nav-link {
  padding: 8px 11px;

  border-radius: 7px;

  color: var(--muted);

  font-size: 12px;

  transition:
    color 0.16s ease,
    background 0.16s ease;
}

.public-nav a:hover,
.nav-link:hover {
  color: var(--text);

  background: rgba(255, 255, 255, 0.035);
}

.nav-actions,
.shell-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

/* ============================================================
   MARCA NOVA DO SHELL
   ============================================================ */

.shell-brand-mark {
  width: 38px;
  height: 38px;

  display: block;

  overflow: hidden;

  border-radius: 8px;

  background: #0a1117;

  border: 1px solid rgba(114, 181, 238, 0.22);
}

.shell-brand-mark img {
  width: 100%;
  height: 100%;
  display: block;
}

.shell-brand-copy {
  display: grid;
  gap: 2px;
}

.shell-brand-copy strong {
  color: #edf2f6;

  font-family: Inter, ui-sans-serif, system-ui, sans-serif;

  font-size: 17px;
  font-weight: 850;
  font-style: normal;

  letter-spacing: -0.055em;
  line-height: 1;
}

.shell-brand-copy small {
  color: #66707a;

  font-size: 6px;
  font-weight: 800;

  letter-spacing: 0.22em;
  line-height: 1;
}

.shell-brand:hover .shell-brand-copy strong {
  color: #fff;
}

