.btn,
.shell-btn {
  min-height: 39px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  padding: 0 13px;

  border-radius: 7px;

  font-size: 12px;
  font-weight: 720;

  cursor: pointer;

  transition:
    background 0.16s ease,
    border-color 0.16s ease,
    color 0.16s ease,
    opacity 0.16s ease;
}

.btn:hover,
.shell-btn:hover {
  transform: none;
}

.btn:active,
.shell-btn:active {
  transform: none;
}

.btn:disabled,
.shell-btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn-primary,
.shell-btn-primary {
  color: #071019;

  background: var(--blue);

  border: 1px solid var(--blue);
}

.btn-primary:hover,
