  border: 1px solid var(--line-strong);
}

.btn-secondary:hover,
.shell-btn-secondary:hover {
  background: #171c21;
  border-color: #38414b;
}

.btn-block {
  width: 100%;
}

.btn-small {
  min-height: 34px;
  padding: 0 11px;
  font-size: 11px;
}

