.section {
  padding: 28px 0 75px;
}

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;

  gap: 18px;

  margin-bottom: 18px;
}

.section-title {
  margin: 0;

  color: var(--text);

  font-size: 27px;
  font-weight: 760;

  line-height: 1.1;

  letter-spacing: -0.038em;
}

.section-subtitle {
  margin: 7px 0 0;

  color: var(--muted);

  font-size: 12px;

  line-height: 1.55;
}

/* ============================================================
   GRID
   ============================================================ */

.grid {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  gap: 1px;

  background: var(--line);

  border: 1px solid var(--line);
}

.grid-2 {
  display: grid;

  grid-template-columns: repeat(2, minmax(0, 1fr));

  gap: 1px;

  background: var(--line);

  border: 1px solid var(--line);
