.card {
  background: var(--panel);

  border: 0;

  border-radius: 0;

  padding: 22px;

  box-shadow: none;
}

.card:hover {
  box-shadow: none;
}

.card-hover {
  transition: background 0.16s ease;
}

.card-hover:hover {
  transform: none;

  background: var(--panel-2);

  border-color: transparent;
}

/* ============================================================
   PRODUTOS
   ============================================================ */

.product-card {
  min-height: 310px;

  display: flex;
  flex-direction: column;
}

.product-cover {
  height: 165px;

  display: grid;
  place-items: center;

  margin: -22px -22px 20px;

  background: linear-gradient(135deg, #171c22, #11151a);

  border-bottom: 1px solid var(--line);

  color: #7e8a95;

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.1em;
}

.product-cover::after {
  display: none;
}

.product-card h2 {
  margin: 12px 0 0;

  color: #edf1f4;

  font-size: 18px;
  font-weight: 720;

  letter-spacing: -0.025em;
}

.product-card p {
  margin: 7px 0 0;

  color: #858e98;

  font-size: 12px;
  line-height: 1.58;
}

.product-card-footer {
  margin-top: auto;

  padding-top: 18px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 10px;
