.form-card {
  width: min(650px, 100%);
  margin: 25px 0 0;
}

.field {
  display: grid;
  gap: 7px;

  margin-top: 15px;
}

.field label {
  color: #aeb5bc;

  font-size: 11px;
  font-weight: 700;
}

.input,
.select,
.textarea {
  width: 100%;

  color: var(--text);

  background: #0b0e12;

  border: 1px solid var(--line);

  border-radius: 7px;

  outline: none;

  transition:
    border-color 0.16s ease,
    background 0.16s ease;
}

.input,
.select {
  min-height: 44px;
  padding: 0 11px;
}

.textarea {
  min-height: 115px;
  padding: 11px;
  resize: vertical;
}

.input::placeholder,
.textarea::placeholder {
  color: #56606a;
}

.input:focus,
.select:focus,
.textarea:focus {
  background: #0d1116;

  border-color: rgba(114, 181, 238, 0.55);

  box-shadow: 0 0 0 2px rgba(114, 181, 238, 0.07);
}

/* ============================================================
   ALERTAS
   ============================================================ */

.alert {
  margin-top: 13px;

  padding: 11px 12px;

  border-radius: 7px;

  background: #11151a;

  border: 1px solid var(--line);

  color: var(--muted);

  font-size: 11px;

  line-height: 1.5;
}

.alert-success {
  color: #7ed8a8;
  border-color: rgba(67, 207, 139, 0.18);
}

.alert-error {
  color: #f08a94;
  border-color: rgba(239, 104, 119, 0.18);
}

.alert-warning {
  color: #dec17e;
  border-color: rgba(226, 185, 105, 0.18);
