.feature-row {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  gap: 0;

  max-width: 1080px;

  margin-top: 38px;

  border-top: 1px solid var(--line);

  border-bottom: 1px solid var(--line);
}

.feature {
  padding: 18px 20px;

  background: transparent;

  border-right: 1px solid var(--line);

  border-radius: 0;
}

.feature:last-child {
  border-right: 0;
}

.feature:hover {
  transform: none;

  background: rgba(255, 255, 255, 0.015);
}

.feature-icon {
  width: auto;
  height: auto;

  display: block;

  padding: 0;

  background: transparent;

  border: 0;

  color: #78838e;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.1em;
}

.feature h3 {
  margin: 10px 0 5px;

  font-size: 13px;
}

.feature p {
  margin: 0;

  color: #79838d;

  font-size: 11px;

  line-height: 1.55;
}

/* ============================================================
   PRODUCT DETAIL
   ============================================================ */

.product-detail {
  width: 100%;
  max-width: 1180px;

  margin: 0;
}

.product-detail-card {
  padding: 30px;
}

.product-detail-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.35fr)
    minmax(320px, 0.65fr);

  gap: 32px;
}

.product-detail h1 {
  margin: 18px 0 0;

  font-size: clamp(38px, 4.2vw, 60px);

  font-weight: 780;

  line-height: 1;

  letter-spacing: -0.06em;
}

.product-detail-description {
  max-width: 760px;

  margin-top: 17px;

  color: var(--muted);

  font-size: 15px;

  line-height: 1.75;
}

.cta-box {
  padding: 23px;

  background: #10151a;

  border: 1px solid var(--line-strong);

  border-radius: 9px;

  box-shadow: none;
}

/* ============================================================
   CHECKOUT
   ============================================================ */

.split {
  width: 100%;

  display: grid;

  grid-template-columns:
    minmax(0, 1.45fr)
    minmax(340px, 0.55fr);

  gap: 1px;

  background: var(--line);

  border: 1px solid var(--line);
}

.split > * {
  background: var(--panel);
}

.summary-card {
  position: sticky;
  top: 90px;
}

.summary-row {
  display: flex;

  justify-content: space-between;

  gap: 15px;

  padding: 13px 0;

  border-bottom: 1px solid var(--line);
}

.summary-total {
  display: flex;

  justify-content: space-between;

  padding-top: 16px;

  border-top: 1px solid var(--line);
}

/* ============================================================
   FILES
   ============================================================ */

.file-list {
  display: grid;

  gap: 0;

  margin-top: 15px;

  border-top: 1px solid var(--line);
}

.file-item {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 14px;

  padding: 13px 0;

  background: transparent;

  border-bottom: 1px solid var(--line);

  border-radius: 0;
}

.file-item:hover {
  background: transparent;
  border-color: var(--line-strong);
}

.file-name strong {
  display: block;

  color: #e4e8ec;

  font-size: 12px;
}

.file-name span {
  display: block;

  margin-top: 3px;

  color: var(--muted-2);

  font-size: 10px;
}

/* ============================================================
   STATS
   ============================================================ */

.stat-grid {
  display: grid;

  grid-template-columns: repeat(4, minmax(0, 1fr));

  gap: 1px;

  background: var(--line);

  border: 1px solid var(--line);
}

.stat {
  padding: 18px;

  background: var(--panel);

  border: 0;

  border-radius: 0;
}

.stat-label {
  color: #737d87;

  font-size: 9px;

  font-weight: 800;

  letter-spacing: 0.09em;

  text-transform: uppercase;
}

.stat-value {
  margin-top: 8px;

  color: #f1f4f7;

  font-size: 27px;

  font-weight: 780;

  letter-spacing: -0.045em;
}

/* ============================================================
   EMPTY
   ============================================================ */

.empty {
  padding: 42px 22px;

  text-align: center;

  background: var(--panel);

  border: 1px dashed #29313a;

  border-radius: 9px;

  color: var(--muted);
}

.empty h3 {
  margin: 0;

  color: var(--text);

  font-size: 15px;
}

.empty p {
  max-width: 500px;

  margin: 9px auto 17px;

  font-size: 12px;

  line-height: 1.6;
}

/* ============================================================
   SUCCESS
   ============================================================ */

.success-panel {
  padding: 28px;

  background: #101619;

  border: 1px solid rgba(67, 207, 139, 0.17);

  border-radius: 9px;

  box-shadow: none;
}

.success-icon {
  width: 46px;
  height: 46px;

  display: grid;
  place-items: center;

  border-radius: 8px;

  background: rgba(67, 207, 139, 0.08);

  color: var(--green);

  font-size: 20px;
}

/* ============================================================
   SKELETON
   ============================================================ */

.skeleton {
  background: #171b20;

  animation: none;
}

/* ============================================================
   FOOTER
   ============================================================ */

.footer {
  padding: 27px 0 35px;

  color: #5f6871;

  border-top: 1px solid var(--line);

  font-size: 10px;
}

.footer-row {
  display: flex;

  justify-content: space-between;

  gap: 15px;

  flex-wrap: wrap;
}

/* ============================================================
   BACK
   ============================================================ */

.back-link {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  margin-bottom: 15px;

  color: #737d87;

  font-size: 10px;
}

.back-link:hover {
  color: #aeb7bf;
}

/* ============================================================
   DASHBOARD / SIDEBAR
   ============================================================ */

.dashboard-shell {
  min-height: 100vh;

  display: flex;

  background: var(--bg);
}

.dashboard-sidebar {
  position: sticky;
  top: 0;

  width: 232px;
  min-width: 232px;
  height: 100vh;

  display: flex;
  flex-direction: column;

  background: #0b0e12;

  border-right: 1px solid var(--line);
}

.dashboard-sidebar-top {
  padding: 15px 14px 16px;

  border-bottom: 1px solid var(--line);
}

.dashboard-sidebar-top .shell-brand-mark {
  width: 36px;
  height: 36px;
}

.dashboard-nav {
  flex: 1;

  overflow-y: auto;

  padding: 16px 9px;

  scrollbar-width: none;
}

.dashboard-nav::-webkit-scrollbar {
  width: 0;
}

.dashboard-nav-group {
  margin-bottom: 18px;
}

.dashboard-nav-title {
  padding: 0 9px 6px;

  color: #515b65;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.dashboard-nav-item {
  min-height: 35px;

  display: flex;

  align-items: center;

  gap: 9px;

  margin: 1px 0;

  padding: 0 9px;

  border-radius: 6px;

  color: #7d8791;

  font-size: 11px;

  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.dashboard-nav-item:hover {
  background: #11151a;

  color: #dfe4e8;
}

.dashboard-nav-item-active {
  color: #e9f3fb !important;

  background: #141b22 !important;

  box-shadow: inset 2px 0 0 var(--blue);
}

.dashboard-nav-icon {
  width: 17px;
  height: 17px;

  display: grid;
  place-items: center;
}

.dashboard-nav-icon svg {
  width: 15px;
  height: 15px;

  fill: none;

  stroke: currentColor;

  stroke-width: 1.5;

  stroke-linecap: round;

  stroke-linejoin: round;
}

.dashboard-sidebar-bottom {
  padding: 10px;

  border-top: 1px solid var(--line);
}

.dashboard-profile {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 8px;

  padding: 8px;

  background: transparent;

  color: #e9edf1;

  text-align: left;

  border-radius: 6px;

  cursor: pointer;
}

.dashboard-profile:hover {
  background: #11151a;
}

.dashboard-profile span:nth-child(2) {
  display: grid;
  gap: 2px;
}

.dashboard-profile strong {
  font-size: 10px;
}

.dashboard-profile small {
  color: #616a74;
  font-size: 8px;
}

.dashboard-avatar {
  width: 29px;
  height: 29px;

  display: grid;
  place-items: center;

  border-radius: 7px;

  background: #1e394d;

  border: 1px solid #305776;

  color: #b7dbf6;

  font-size: 10px;

  font-weight: 850;
}

.dashboard-logout {
  width: 100%;

  margin-top: 2px;

  padding: 7px 8px;

  background: transparent;

  color: #5f6872;

  font-size: 9px;

  text-align: left;

  cursor: pointer;

  border-radius: 6px;
}

.dashboard-logout:hover {
  color: #ea929c;

  background: rgba(239, 104, 119, 0.04);
}

.dashboard-main {
  flex: 1;
  min-width: 0;
}

.dashboard-topbar {
  height: 60px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 0 21px;

  background: #0b0e12;

  border-bottom: 1px solid var(--line);
}

.dashboard-search {
  width: 380px;
  max-width: 45vw;
  height: 34px;

  display: flex;
  align-items: center;

  gap: 8px;

  padding: 0 10px;

  background: #0e1217;

  border: 1px solid var(--line);

  border-radius: 6px;

  color: #626c76;

  font-size: 10px;
}

.dashboard-search-icon {
  width: 14px;
  height: 14px;
}

.dashboard-search-icon svg {
  width: 14px;
  height: 14px;

  fill: none;

  stroke: currentColor;

  stroke-width: 1.6;
}

.dashboard-search kbd {
  margin-left: auto;

  padding: 2px 5px;

  color: #59636e;

  background: transparent;

  border: 1px solid var(--line);

  border-radius: 4px;

  font-size: 8px;
}

.dashboard-top-actions {
  display: flex;

  align-items: center;

  gap: 11px;
}

.dashboard-icon-button {
  width: 32px;
  height: 32px;

  display: grid;
  place-items: center;

  background: transparent;

  color: #6b7580;

  border-radius: 6px;

  cursor: pointer;
}

.dashboard-icon-button:hover {
  background: #11151a;
  color: #dce2e7;
}

.dashboard-icon-button svg {
  width: 16px;
  height: 16px;

  fill: none;

  stroke: currentColor;

  stroke-width: 1.5;

  stroke-linecap: round;

  stroke-linejoin: round;
}

.dashboard-content {
  padding: 27px 28px 60px;
}

.dashboard-page-head {
  display: flex;

  align-items: end;

  justify-content: space-between;

  gap: 18px;

  margin-bottom: 22px;
}

.dashboard-page-head h1 {
  margin: 0;

  color: #edf1f4;

  font-size: 29px;

  font-weight: 760;

  line-height: 1;

  letter-spacing: -0.045em;
}

.dashboard-page-head p {
  margin: 7px 0 0;

  color: #737d87;

  font-size: 11px;

  line-height: 1.5;
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 1100px) {
  .container {
    width: calc(100% - 40px);
    margin-left: 20px;
    margin-right: 20px;
  }

  .grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .feature-row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .split,
  .product-detail-grid {
    grid-template-columns: 1fr;
  }

  .summary-card {
    position: static;
  }
}

@media (max-width: 767px) {
  .container {
    width: calc(100% - 20px);
    margin-left: 10px;
    margin-right: 10px;
  }

  .nav,
  .shell-nav {
    min-height: 62px;
  }

  .public-nav {
    display: none;
  }

  .nav-actions .btn-primary,
  .shell-actions .shell-btn-primary {
    display: none;
  }

  .hero {
    min-height: auto;
    padding: 52px 0 65px;
  }

  .display {
    font-size: clamp(39px, 12vw, 57px);
  }

  .lead {
    font-size: 15px;
  }

  .hero-actions {
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .grid,
  .grid-2,
  .feature-row,
  .stat-grid {
    grid-template-columns: 1fr;
  }

  .feature {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .feature:last-child {
    border-bottom: 0;
  }

  .card {
    padding: 18px;
  }

  .product-cover {
    margin: -18px -18px 18px;
  }

  .product-card {
    min-height: 0;
  }

  .product-card-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .product-card-footer .btn {
    width: 100%;
  }

  .dashboard-sidebar {
    display: none;
  }

  .dashboard-topbar {
    height: 57px;
    padding: 0 10px;
  }

  .dashboard-search {
    width: 100%;
    max-width: none;
  }

  .dashboard-top-actions {
    display: none;
  }

  .dashboard-content {
    padding: 22px 10px 55px;
  }

  .dashboard-page-head h1 {
    font-size: 26px;
  }

  .file-item {
    align-items: flex-start;
    flex-direction: column;
  }

  .file-item .btn {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .container {
    width: calc(100% - 16px);
    margin-left: 8px;
    margin-right: 8px;
  }

  .nav-brand > span:last-child {
    font-size: 16px;
  }

  .nav-logo {
    width: 36px;
    height: 36px;
    background-size: 36px 36px;
  }

  .display {
    font-size: clamp(36px, 13vw, 50px);
  }
}

/* TZ PRODUCER DATA SCREENS */

.section-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.section-toolbar-left {
  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 0;
}

.section-search {
  width: min(390px, 42vw);
  height: 37px;

  display: flex;
  align-items: center;
  gap: 8px;

  padding: 0 10px;

  background: #0c1014;

  border: 1px solid var(--line);

  border-radius: 7px;
}

.section-search svg {
  width: 14px;
  height: 14px;

  flex: 0 0 auto;

  fill: none;
  stroke: #68727c;
  stroke-width: 1.7;
  stroke-linecap: round;
}

.section-search input {
  width: 100%;
  height: 100%;

  padding: 0;

  color: #e3e7eb;

  background: transparent;

  border: 0;
  outline: 0;

  font-size: 10px;
}

.section-search input::placeholder {
  color: #59636d;
}

.section-count {
  white-space: nowrap;

  color: #68727c;

  font-size: 10px;
}

.section-table {
  width: 100%;

  overflow: hidden;

  background: #0d1115;

  border: 1px solid var(--line);

  border-radius: 8px;
}

.section-table-head,
.section-table-row {
  display: grid;

  align-items: center;

  min-height: 54px;

  padding: 0 15px;

  gap: 16px;
}

.section-table-head {
  min-height: 39px;

  color: #5f6872;

  background: #0a0d11;

  border-bottom: 1px solid var(--line);

  font-size: 8px;
  font-weight: 850;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.section-table-row {
  min-height: 65px;

  border-bottom: 1px solid var(--line);

  color: #d9dee3;

  font-size: 11px;

  transition: background 0.15s ease;
}

.section-table-row:last-child {
  border-bottom: 0;
}

.section-table-row:hover {
  background: #11161b;
}

.section-products-grid {
  grid-template-columns:
    minmax(230px, 2fr)
    minmax(110px, 0.8fr)
    minmax(100px, 0.7fr)
    minmax(105px, 0.75fr)
    52px;
}

.section-offers-grid {
  grid-template-columns:
    minmax(220px, 1.5fr)
    minmax(180px, 1fr)
    minmax(110px, 0.7fr)
    minmax(100px, 0.6fr);
}

.section-files-grid {
  grid-template-columns:
    minmax(240px, 1.5fr)
    minmax(170px, 1fr)
    minmax(130px, 0.75fr)
    minmax(100px, 0.6fr);
}

.section-main-cell {
  min-width: 0;
}

.section-main-cell strong {
  display: block;

  overflow: hidden;

  color: #eef1f3;

  font-size: 12px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.section-main-cell small {
  display: block;

  overflow: hidden;

  margin-top: 4px;

  color: #5e6872;

  font-size: 9px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.section-muted-cell {
  overflow: hidden;

  color: #7e8892;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.section-status {
  width: max-content;

  color: #707a84;

  font-size: 9px;

  font-weight: 800;

  text-transform: uppercase;
}

.section-status-success {
  color: #67c797;
}

.section-status-warning {
  color: #d2ad67;
}

.section-status-danger {
  color: #c54b57 !important;
}

.section-more {
  min-height: 30px;

  padding: 0 8px;

  color: #7d8994;

  background: transparent;

  border: 1px solid transparent;

  border-radius: 6px;

  font-size: 9px;

  cursor: pointer;
}

.section-more:hover {
  color: #b9d6ef;

  background: #131a21;

  border-color: #273643;
}

.section-empty {
  min-height: 340px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  padding: 45px 25px;

  text-align: center;

  border: 1px dashed #29323a;

  border-radius: 8px;

  background: #0d1115;
}

.section-empty-symbol {
  margin-bottom: 15px;

  color: #4c5761;

  font-size: 24px;

  line-height: 1;
}

.section-empty h2 {
  margin: 0;

  color: #e9edf0;

  font-size: 17px;

  font-weight: 740;

  letter-spacing: -0.025em;
}

.section-empty p {
  width: min(520px, 100%);

  margin: 9px 0 19px;

  color: #727c86;

  font-size: 11px;

  line-height: 1.65;
}

.section-loading-row {
  min-height: 65px;

  display: grid;

  grid-template-columns:
    2fr
    0.8fr
    0.7fr
    0.6fr;

  gap: 16px;

  align-items: center;

  padding: 0 15px;

  border-bottom: 1px solid var(--line);
}

.section-loading-row span {
  height: 10px;

  border-radius: 4px;

  background: #181d23;

  opacity: 0.8;
}

@media (max-width: 900px) {
  .section-products-grid {
    grid-template-columns:
      minmax(190px, 2fr)
      minmax(100px, 0.8fr)
      minmax(85px, 0.7fr)
      50px;
  }

  .section-products-grid > span:nth-child(2) {
    display: none;
  }

  .section-offers-grid {
    grid-template-columns:
      minmax(190px, 1.5fr)
      minmax(140px, 1fr)
      minmax(90px, 0.7fr);
  }

  .section-offers-grid > span:nth-child(2) {
    display: none;
  }
}

@media (max-width: 767px) {
  .section-toolbar {
    align-items: stretch;

    flex-direction: column;
  }

  .section-toolbar-left {
    align-items: stretch;

    flex-direction: column;
  }

  .section-search {
    width: 100%;
  }

  .section-toolbar .btn {
    width: 100%;
  }

  .section-table {
    overflow-x: auto;
  }

  .section-table-head,
  .section-table-row {
    min-width: 650px;
  }

  .section-empty {
    min-height: 280px;
  }
}
/* TZ SECTION FORMS */

.section-form-panel {
  margin-bottom: 18px;
  padding: 18px;
  background: #0d1115;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.section-form-panel h2 {
  margin: 5px 0 0;
  color: #edf1f4;
  font-size: 18px;
  font-weight: 740;
  letter-spacing: -0.025em;
}

.section-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 15px;
}

.section-form-grid .btn {
  width: max-content;
}

@media (max-width: 767px) {
  .section-form-grid {
    grid-template-columns: 1fr;
  }

  .section-form-grid textarea {
    grid-column: auto !important;
  }

  .section-form-grid .btn {
    width: 100%;
  }
}

/* TZ PRODUCT PAGE */

.product-page {
  padding-top: 28px;
  padding-bottom: 70px;
}

.product-back {
  display: inline-flex;
  align-items: center;

  color: #6f7983;

  font-size: 11px;
}

.product-back:hover {
  color: #dce3e8;
}

.product-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    390px;

  gap: 55px;

  margin-top: 28px;

  max-width: 1320px;
}

.product-main {
  padding-top: 12px;
}

.product-meta {
  display: flex;
  align-items: center;
  gap: 8px;

  color: #66717c;

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.product-title {
  max-width: 900px;

  margin: 17px 0 0;

  color: #f1f4f6;

  font-size: clamp(43px, 4.5vw, 69px);

  line-height: 0.99;

  letter-spacing: -0.065em;

  font-weight: 790;
}

.product-description {
  max-width: 760px;

  margin: 19px 0 0;

  color: #8d969f;

  font-size: 15px;

  line-height: 1.78;
}

.product-divider {
  width: 100%;
  height: 1px;

  margin: 38px 0 32px;

  background: var(--line);
}

.product-section h2 {
  margin: 0 0 17px;

  color: #e8edf1;

  font-size: 17px;

  font-weight: 730;

  letter-spacing: -0.02em;
}

.product-benefits {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  border-top: 1px solid var(--line);

  border-bottom: 1px solid var(--line);
}

.product-benefit {
  min-height: 95px;

  display: flex;

  align-items: center;

  gap: 12px;

  padding: 18px;

  border-right: 1px solid var(--line);

  color: #a0a8b0;

  font-size: 11px;
}

.product-benefit:last-child {
  border-right: 0;
}

.product-benefit-number {
  color: #607080;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.08em;
}

.product-trust {
  display: grid;

  grid-template-columns: repeat(2, minmax(0, 1fr));

  gap: 0;

  margin-top: 30px;

  border-top: 1px solid var(--line);

  border-bottom: 1px solid var(--line);
}

.product-trust > div {
  display: grid;
  gap: 5px;

  padding: 18px 0;
}

.product-trust > div + div {
  padding-left: 22px;

  border-left: 1px solid var(--line);
}

.product-trust strong {
  color: #dce2e7;

  font-size: 11px;
}

.product-trust span {
