    justify-content: center;

    flex-direction: column;
  }

  .home-v3-footer-inner {
    min-height: 105px;

    grid-template-columns: 1fr;

    justify-items: start;
  }

  .home-v3-footer-inner nav {
    flex-wrap: wrap;
  }

  .home-v3-footer-inner > small {
    display: none;
  }
}
/* TZ HOME V4 */

.tz-home-v4 {
  min-height: 100vh;

  background: #0b0d10;

  color: #eef2f4;
}

/* HEADER */

.tz-home-v4 .site-header {
  position: relative;

  background: #0b0d10;

  border-bottom: 1px solid #1d242a;
}

.tz-home-v4 .shell-container {
  width: calc(100% - 56px);
  margin-left: 28px;
  margin-right: 28px;
}

/* ============================================================
   HERO
   ============================================================ */

.tz-v4-hero {
  border-bottom: 1px solid #1d242a;
}

.tz-v4-hero-inner {
  min-height: 690px;

  display: grid;

  grid-template-columns:
    minmax(0, 1.15fr)
    minmax(400px, 0.85fr);

  align-items: center;

  gap: 85px;

  padding-top: 64px;
  padding-bottom: 64px;
}

.tz-v4-hero-copy {
  max-width: 790px;
}

.tz-v4-label {
  display: block;

  margin-bottom: 21px;

  color: #64717d;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.16em;
}

.tz-v4-hero-copy h1 {
  margin: 0;

  color: #f2f4f5;

  font-size: clamp(54px, 6.6vw, 92px);

  line-height: 0.91;

  font-weight: 750;

  letter-spacing: -0.075em;
}

.tz-v4-hero-copy > p {
  max-width: 570px;

  margin: 26px 0 0;

  color: #89929a;

  font-size: 15px;

  line-height: 1.72;
}

.tz-v4-hero-actions {
  display: flex;

  align-items: center;

  gap: 18px;

  margin-top: 32px;
}

.tz-v4-action-main,
.tz-v4-action-link {
  min-height: 45px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 9px;

  padding: 0 16px;

  border-radius: 6px;

  font-size: 10px;

  font-weight: 760;
}

.tz-v4-action-main {
  color: #081018;

  background: #85b7dd;

  border: 1px solid #85b7dd;
}

.tz-v4-action-main:hover {
  background: #9cc8e8;

  border-color: #9cc8e8;
}

.tz-v4-action-main span {
  font-size: 13px;
}

.tz-v4-action-link {
  min-height: 45px;

  padding-left: 0;
  padding-right: 0;

  color: #b2bcc4;

  background: transparent;

  border: 0;

  border-bottom: 1px solid #39444e;

  border-radius: 0;
}

.tz-v4-action-link:hover {
  color: #f0f3f5;

  border-color: #7aa7c8;
}

/* HERO SIDE */

.tz-v4-hero-side {
  width: 100%;

  background: #0e1216;

  border: 1px solid #2a333a;

  border-radius: 8px;

  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.25);
}

.tz-v4-side-heading {
  min-height: 67px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 16px;

  padding: 0 17px;

  border-bottom: 1px solid #20272d;
}

.tz-v4-side-heading span {
  color: #68747e;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-v4-side-heading a {
  color: #82aacb;

  font-size: 9px;
}

.tz-v4-live-list {
  border-bottom: 1px solid #20272d;
}

.tz-v4-live-item {
  min-height: 82px;

  display: grid;

  grid-template-columns:
    25px
    44px
    minmax(0, 1fr)
    20px;

  align-items: center;

  gap: 10px;

  padding: 0 15px;

  border-bottom: 1px solid #1c232a;

  transition: background 0.15s ease;
}

.tz-v4-live-item:last-child {
  border-bottom: 0;
}

.tz-v4-live-item:hover {
  background: #12181d;
}

.tz-v4-live-index {
  color: #4e5963;

  font-size: 8px;

  font-weight: 850;
}

.tz-v4-live-cover {
  width: 44px;
  height: 44px;

  overflow: hidden;

  display: grid;

  place-items: center;

  background: #17212a;

  border: 1px solid #2a3b49;

  border-radius: 5px;

  color: #82afcf;

  font-size: 8px;

  font-weight: 900;
}

.tz-v4-live-cover img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
}

.tz-v4-live-copy {
  min-width: 0;

  display: grid;

  gap: 4px;
}

.tz-v4-live-copy strong {
  overflow: hidden;

  color: #e5eaed;

  font-size: 10px;

  font-weight: 690;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-v4-live-copy small {
  color: #626e78;

  font-size: 8px;

  text-transform: uppercase;

  letter-spacing: 0.05em;
}

.tz-v4-live-arrow {
  color: #56616b;

  font-size: 12px;
}

.tz-v4-live-item:hover .tz-v4-live-arrow {
  color: #8db8d9;
}

.tz-v4-live-foot {
  min-height: 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 11px;

  color: #515d67;

  font-size: 7px;

  font-weight: 760;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.tz-v4-live-foot i {
  width: 3px;
  height: 3px;

  border-radius: 50%;

  background: #46515b;
}

/* ============================================================
   DISCOVERY BAR
   ============================================================ */

.tz-v4-discovery-bar {
  border-bottom: 1px solid #1d242a;
}

.tz-v4-discovery-inner {
  min-height: 62px;

  display: flex;

  align-items: center;

  gap: 26px;

  overflow-x: auto;
}

.tz-v4-discovery-inner > span {
  color: #596671;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.11em;
}

.tz-v4-discovery-inner > a {
  color: #78848e;

  font-size: 9px;

  white-space: nowrap;
}

.tz-v4-discovery-inner > a:hover {
  color: #d9e0e5;
}

.tz-v4-discovery-all {
  margin-left: auto;

  color: #81aacb !important;

  font-weight: 700;
}

/* ============================================================
   GENERIC SECTION
   ============================================================ */

.tz-v4-section {
  padding-top: 94px;
  padding-bottom: 94px;
}

.tz-v4-section-head {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    300px;

  align-items: end;

  gap: 40px;

  margin-bottom: 27px;
}

.tz-v4-section-head > div > span {
  color: #a27576;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.13em;
}

.tz-v4-section-head h2 {
  margin: 10px 0 0;

  color: #edf1f3;

  font-size: clamp(31px, 3.8vw, 48px);

  line-height: 0.99;

  font-weight: 740;

  letter-spacing: -0.055em;
}

.tz-v4-section-head > p {
  margin: 0;

  color: #737f88;

  font-size: 10px;

  line-height: 1.65;
}

/* ============================================================
   PRODUCTS
   ============================================================ */

.tz-v4-products {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  gap: 1px;

  background: #222a31;

  border: 1px solid #222a31;
}

.tz-v4-product {
  display: block;

  background: #0d1115;

  transition: background 0.16s ease;
}

.tz-v4-product:hover {
  background: #11171c;
}

.tz-v4-product-media {
  height: 265px;

  display: grid;

  place-items: center;

  overflow: hidden;

  background: linear-gradient(135deg, #182028 0%, #0e1419 100%);

  border-bottom: 1px solid #222a31;
}

.tz-v4-product-media img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transition: transform 0.35s ease;
}

.tz-v4-product:hover .tz-v4-product-media img {
  transform: scale(1.025);
}

.tz-v4-product-media span {
  color: #5b7182;

  font-size: 22px;

  font-weight: 900;

  letter-spacing: -0.08em;
}

.tz-v4-product-info {
  min-height: 98px;

  display: grid;

  grid-template-columns:
    28px
    minmax(0, 1fr)
    70px
    23px;

  align-items: center;

  gap: 12px;

  padding: 0 15px;
}

.tz-v4-product-number {
  color: #4e5963;

  font-size: 8px;

  font-weight: 850;
}

.tz-v4-product-info > div {
  min-width: 0;
}

.tz-v4-product-info strong {
  display: block;

  overflow: hidden;

  color: #e5eaed;

  font-size: 11px;

  font-weight: 700;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-v4-product-info p {
  overflow: hidden;

  margin: 5px 0 0;

  color: #69747e;

  font-size: 8px;

  line-height: 1.45;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-v4-product-category {
  color: #68747d;

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.06em;

  text-align: right;

  text-transform: uppercase;
}

.tz-v4-product-arrow {
  color: #58636d;

  font-size: 12px;

  text-align: right;
}

.tz-v4-product:hover .tz-v4-product-arrow {
  color: #8eb9d9;
}

.tz-v4-empty-products {
  min-height: 175px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  padding: 25px;

  background: #0d1115;

  border: 1px solid #232b33;

  border-radius: 7px;
}

.tz-v4-empty-products > div {
  display: grid;

  gap: 6px;
}

.tz-v4-empty-products strong {
  color: #e6ebee;

  font-size: 12px;
}

.tz-v4-empty-products span {
  color: #68747e;

  font-size: 9px;
}

/* ============================================================
   PEOPLE
   ============================================================ */

.tz-v4-people {
  border-top: 1px solid #20272e;

  border-bottom: 1px solid #20272e;

  background: #0d1115;
}

.tz-v4-people-grid {
  min-height: 500px;

  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    1px
    minmax(0, 1fr);

  gap: 0;
}

.tz-v4-person {
  display: flex;

  flex-direction: column;

  padding: 67px 48px;
}

.tz-v4-person:first-child {
  padding-left: 0;
}

.tz-v4-person:last-child {
  padding-right: 0;
}

.tz-v4-person-number {
  color: #4e5963;

  font-size: 8px;

  font-weight: 850;
}

.tz-v4-person-label {
  margin-top: 31px;

  color: #8e686a;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-v4-person h2 {
  max-width: 520px;

  margin: 12px 0 0;

  color: #ebeff2;

  font-size: clamp(29px, 3vw, 42px);

  line-height: 1.02;

  font-weight: 740;

  letter-spacing: -0.052em;
}

.tz-v4-person p {
  max-width: 440px;

  margin: 18px 0 0;

  color: #737e88;

  font-size: 11px;

  line-height: 1.65;
}

.tz-v4-person a {
  width: max-content;

  margin-top: auto;

  padding-bottom: 4px;

  color: #82aaca;

  border-bottom: 1px solid #314454;

  font-size: 9px;

  font-weight: 700;
}

.tz-v4-person a:hover {
  color: #d7e4ed;

  border-color: #789fbd;
}

.tz-v4-people-divider {
  background: #20272e;
}

/* ============================================================
   FINAL
   ============================================================ */

.tz-v4-final {
  border-bottom: 1px solid #20272e;
}

.tz-v4-final-inner {
  min-height: 375px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 35px;
}

.tz-v4-final-inner > div:first-child > span {
  color: #607487;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-v4-final h2 {
  margin: 11px 0 0;

  color: #f0f3f5;

  font-size: clamp(36px, 4.8vw, 62px);

  line-height: 0.96;

  font-weight: 750;

  letter-spacing: -0.065em;
}

.tz-v4-final-actions {
  display: grid;

  width: min(390px, 100%);
}

.tz-v4-final-link {
  min-height: 62px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 0 1px;

  color: #cfd6db;

  border-top: 1px solid #273039;

  font-size: 12px;

  font-weight: 700;
}

.tz-v4-final-link:last-child {
  border-bottom: 1px solid #273039;
}

.tz-v4-final-link span {
  color: #637582;

  font-size: 14px;
}

.tz-v4-final-link:hover {
  color: #93bbda;
}

.tz-v4-final-link:hover span {
  color: #93bbda;
}

/* ============================================================
   FOOTER
   ============================================================ */

.tz-v4-footer {
  background: #090b0e;
}

.tz-v4-footer-inner {
  min-height: 88px;

  display: grid;

  grid-template-columns: 1fr auto 1fr;

  align-items: center;

  gap: 25px;
}

.tz-v4-footer-brand {
  display: flex;

  align-items: center;

  gap: 8px;
}

.tz-v4-footer-brand span {
  width: 26px;
  height: 26px;

  display: grid;

  place-items: center;

  background: #111b23;

  border: 1px solid #293b49;

  border-radius: 5px;

  color: #85aecc;

  font-size: 6px;

  font-weight: 900;
}

.tz-v4-footer-brand strong {
  color: #c7cfd5;

  font-size: 9px;

  letter-spacing: -0.01em;
}

.tz-v4-footer-inner nav {
  display: flex;

  align-items: center;

  gap: 19px;
}

.tz-v4-footer-inner nav a {
  color: #5e6973;

  font-size: 8px;
}

.tz-v4-footer-inner nav a:hover {
  color: #ccd4da;
}

.tz-v4-footer-inner > small {
  justify-self: end;

  color: #4e5861;

  font-size: 7px;
}

/* ============================================================
   1100 / TABLET
   ============================================================ */

@media (max-width: 1100px) {
  .tz-v4-hero-inner {
    grid-template-columns: 1fr;

    gap: 45px;

    padding-top: 55px;
    padding-bottom: 60px;
  }

  .tz-v4-hero-side {
    width: min(700px, 100%);
  }

  .tz-v4-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 767px) {
  .tz-home-v4 .container {
    width: calc(100% - 20px);

    margin-left: 10px;
    margin-right: 10px;
  }

  .tz-home-v4 .shell-container {
    width: calc(100% - 20px);

    margin-left: 10px;
    margin-right: 10px;
  }

  .tz-v4-hero-inner {
    min-height: auto;

    padding-top: 45px;
    padding-bottom: 45px;

    gap: 35px;
  }

  .tz-v4-hero-copy h1 {
    font-size: clamp(40px, 12vw, 57px);

    line-height: 0.95;
  }

  .tz-v4-hero-copy > p {
    margin-top: 18px;

    font-size: 14px;
  }

  .tz-v4-hero-actions {
    align-items: stretch;

    flex-direction: column;

    gap: 13px;

    margin-top: 24px;
  }

  .tz-v4-action-main {
    width: 100%;
  }

  .tz-v4-action-link {
    width: max-content;
  }

  .tz-v4-live-item {
    grid-template-columns:
      23px
      42px
      minmax(0, 1fr)
      15px;

    min-height: 76px;

    padding-left: 11px;
    padding-right: 11px;
  }

  .tz-v4-live-cover {
    width: 42px;
    height: 42px;
  }

  .tz-v4-discovery-inner {
    min-height: 57px;

    gap: 20px;
  }

  .tz-v4-discovery-all {
    margin-left: 0;
  }

  .tz-v4-section {
    padding-top: 60px;
    padding-bottom: 60px;
  }

  .tz-v4-section-head {
    grid-template-columns: 1fr;

    gap: 13px;
  }

  .tz-v4-section-head h2 {
    font-size: 30px;
  }

  .tz-v4-products {
    grid-template-columns: 1fr;
  }

  .tz-v4-product-media {
    height: 220px;
  }

  .tz-v4-product-info {
    grid-template-columns:
      25px
      minmax(0, 1fr)
      23px;
  }

  .tz-v4-product-category {
    display: none;
  }

  .tz-v4-people-grid {
    min-height: auto;

    grid-template-columns: 1fr;
  }

  .tz-v4-person,
  .tz-v4-person:first-child,
  .tz-v4-person:last-child {
    padding: 55px 10px;
  }

  .tz-v4-person:last-child {
    padding-top: 40px;
  }

  .tz-v4-people-divider {
    width: 100%;
    height: 1px;
  }

  .tz-v4-person h2 {
    font-size: 30px;
  }

  .tz-v4-person p {
    font-size: 11px;
  }

  .tz-v4-person a {
    margin-top: 34px;
  }

  .tz-v4-final-inner {
    min-height: 380px;

    align-items: flex-start;

    justify-content: center;

    flex-direction: column;
  }

  .tz-v4-final-actions {
    width: 100%;
  }

  .tz-v4-footer-inner {
    min-height: 112px;

    grid-template-columns: 1fr;

    justify-items: start;
  }

  .tz-v4-footer-inner nav {
    flex-wrap: wrap;

    gap: 13px;
  }

  .tz-v4-footer-inner > small {
    display: none;
  }
}
/* TZ HOME V4 FINAL REFINEMENT */

