.tz-final-product-icon.muted {
  color: #6b6472;

  background: #17141b;

  border-color: #2d2834;

  font-size: 12px;
}

.tz-final-product-info {
  min-width: 0;

  display: grid;

  gap: 4px;
}

.tz-final-product-info strong {
  overflow: hidden;

  color: #e7e1e9 !important;

  font-size: 9px;

  font-weight: 690;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-final-product-info small {
  color: #696170;

  font-size: 7px;

  text-transform: uppercase;

  letter-spacing: 0.05em;
}

.tz-final-arrow {
  color: #595260;

  font-size: 11px;
}

.tz-final-product-row:hover .tz-final-arrow {
  color: #a889c4;
}

.tz-final-market-foot {
  min-height: 43px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 0 14px;

  color: #57515e;

  font-size: 6px;

  text-transform: uppercase;

  letter-spacing: 0.07em;
}

/* DISCOVERY */

.tz-final-discovery {
  border-bottom: 1px solid var(--z-line);

  background: #0f0e14 !important;
}

.tz-final-discovery-inner {
  min-height: 61px;

  display: flex;

  align-items: center;

  gap: 25px;

  overflow-x: auto;
}

.tz-final-discovery-inner > span {
  color: #6a6274;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.13em;
}

.tz-final-discovery-inner a {
  color: #77717e !important;

  font-size: 8px;

  white-space: nowrap;
}

.tz-final-discovery-inner a:hover {
  color: #e0dbe3 !important;
}

.tz-final-discovery-all {
  margin-left: auto;

  color: #9b80b9 !important;

  font-weight: 700;
}

/* SECTIONS */

.tz-final-section {
  padding: 90px 0;
}

.tz-final-section-head {
  display: flex;

  align-items: end;

  justify-content: space-between;

  gap: 30px;

  margin-bottom: 25px;
}

.tz-final-section-head div {
  display: grid;

  gap: 7px;
}

.tz-final-section-head div > span {
  color: #756c7d;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.13em;
}

.tz-final-section-head h2 {
  margin: 0;

  color: #eee9ef !important;

  font-size: clamp(31px, 3.5vw, 44px);

  line-height: 0.98;

  font-weight: 740;

  letter-spacing: -0.055em;
}

.tz-final-section-head > a {
  color: #957bb2 !important;

  font-size: 8px;

  font-weight: 700;
}

.tz-final-product-grid {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  gap: 1px;

  background: #292532;

  border: 1px solid #292532;
}

.tz-final-product-card {
  background: #14121a;

  transition: background 0.16s ease;
}

.tz-final-product-card:hover {
  background: #191620;
}

.tz-final-product-cover {
  height: 280px;

  position: relative;

  display: grid;

  place-items: center;

  background: radial-gradient(
    circle at 50% 40%,
    #2a2134 0%,
    #17141c 44%,
    #100e14 100%
  );

  border-bottom: 1px solid #292532;
}

.tz-final-product-cover span {
  color: #aa8ac6;

  font-size: 31px;

  font-weight: 900;

  letter-spacing: -0.08em;
}

.tz-final-product-cover small {
  position: absolute;

  left: 15px;
  bottom: 13px;

  color: #625a68;

  font-size: 7px;

  font-weight: 850;
}

.tz-final-product-card-info {
  min-height: 92px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  padding: 0 15px;
}

.tz-final-product-card-info div {
  min-width: 0;
}

.tz-final-product-card-info strong {
  display: block;

  overflow: hidden;

  color: #e8e2ea !important;

  font-size: 10px;

  font-weight: 700;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-final-product-card-info p {
  overflow: hidden;

  margin: 5px 0 0 !important;

  color: #69616f !important;

  font-size: 7px !important;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.tz-final-product-card-info > span {
  color: #726a79;

  font-size: 6px;

  font-weight: 800;

  letter-spacing: 0.05em;

  text-transform: uppercase;
}

.tz-final-empty {
  min-height: 205px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  padding: 25px;

  background: #14121a;

  border: 1px solid #292532;

  border-radius: 7px;
}

.tz-final-empty div {
  display: grid;

  gap: 6px;
}

.tz-final-empty div > span {
  color: #776e7e;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-final-empty strong {
  color: #e8e3e9 !important;

  font-size: 12px;
}

.tz-final-empty p {
  margin: 0 !important;

  color: #756d7b !important;

  font-size: 8px !important;
}

.tz-final-secondary-button {
  min-height: 40px;

  display: inline-flex;

  align-items: center;

  gap: 8px;

  padding: 0 12px;

  color: #ddd6e2 !important;

  background: #1a1722;

  border: 1px solid #3a3344;

  border-radius: 5px;

  font-size: 8px;

  font-weight: 700;
}

/* ECOSYSTEM */

.tz-final-ecosystem {
  padding: 92px 0;

  background: #0f0e14 !important;

  border-top: 1px solid var(--z-line);

  border-bottom: 1px solid var(--z-line);
}

.tz-final-ecosystem-head {
  margin-bottom: 25px;
}

.tz-final-ecosystem-head > span {
  color: #756c7d;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.13em;
}

.tz-final-ecosystem-head h2 {
  margin: 9px 0 0;

  color: #eee9ef !important;

  font-size: clamp(29px, 3.4vw, 43px);

  line-height: 0.98;

  font-weight: 740;

  letter-spacing: -0.055em;
}

.tz-final-role-grid {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  gap: 1px;

  background: #292532;

  border: 1px solid #292532;
}

.tz-final-role {
  min-height: 275px;

  position: relative;

  display: flex;

  flex-direction: column;

  padding: 21px;

  background: #14121a;
}

.tz-final-role:hover {
  background: #1a1721;
}

.tz-final-role-primary {
  background: linear-gradient(180deg, #181422 0%, #14121a 100%);
}

.tz-final-role-number {
  color: #554e5d;

  font-size: 7px;

  font-weight: 850;
}

.tz-final-role > small {
  margin-top: 35px;

  color: #8f79a7;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-final-role h3 {
  margin: 9px 0 0;

  color: #ece7ed !important;

  font-size: 20px;

  font-weight: 710;

  letter-spacing: -0.03em;
}

.tz-final-role p {
  max-width: 300px;

  margin: 9px 0 0 !important;

  color: #76707c !important;

  font-size: 9px !important;

  line-height: 1.65 !important;
}

.tz-final-role b {
  margin-top: auto;

  align-self: flex-end;

  color: #655d6f;

  font-size: 14px;
}

.tz-final-role:hover b {
  color: #a889c4;
}

/* CTA */

.tz-final-cta {
  padding: 95px 0;

  border-bottom: 1px solid var(--z-line);
}

.tz-final-cta-inner {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 45px;
}

.tz-final-cta-inner > div:first-child {
  display: grid;

  gap: 8px;
}

.tz-final-cta-inner > div:first-child > span {
  color: #766c7e;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-final-cta h2 {
  margin: 0;

  color: #eee9ef !important;

  font-size: clamp(36px, 4.5vw, 58px);

  line-height: 0.96;

  font-weight: 740;

  letter-spacing: -0.06em;
}

.tz-final-cta-links {
  width: min(370px, 100%);

  display: grid;
}

.tz-final-cta-links a {
  min-height: 56px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  color: #d2ccd5 !important;

  border-top: 1px solid #302a38;

  font-size: 10px;

  font-weight: 700;
}

.tz-final-cta-links a:last-child {
  border-bottom: 1px solid #302a38;
}

.tz-final-cta-links a span {
  color: #645a6d;

  font-size: 13px;
}

.tz-final-cta-links a:hover,
.tz-final-cta-links a:hover span {
  color: #a889c4 !important;
}

/* FOOTER */

.tz-final-footer {
  background: #09080c !important;
}

.tz-final-footer-main {
  min-height: 185px;

  display: grid;

  grid-template-columns:
    minmax(250px, 1.6fr)
    repeat(3, minmax(120px, 1fr));

  gap: 35px;

  padding: 40px 0 35px;

  border-bottom: 1px solid #292532;
}

.tz-final-footer-about {
  max-width: 300px;
}

.tz-final-footer-about p {
  margin: 12px 0 0 !important;

  color: #5f5866 !important;

  font-size: 8px !important;

  line-height: 1.65 !important;
}

.tz-final-footer-column {
  display: grid;

  align-content: start;

  gap: 8px;
}

.tz-final-footer-column > span {
  margin-bottom: 3px;

  color: #726979;

  font-size: 7px;

  font-weight: 850;

  letter-spacing: 0.12em;
}

.tz-final-footer-column a {
  width: max-content;

  color: #605a67 !important;

  font-size: 8px;
}

.tz-final-footer-column a:hover {
  color: #a889c4 !important;
}

.tz-final-footer-bottom {
  min-height: 54px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  color: #4e4855;

  font-size: 7px;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1050px) {
  .tz-final-header-inner {
    grid-template-columns: 1fr auto;
  }

  .tz-final-nav {
    display: none;
  }

  .tz-final-hero-grid {
    grid-template-columns: 1fr;

    gap: 48px;

    padding: 58px 0 65px;
  }

  .tz-final-market {
    width: min(700px, 100%);
  }

  .tz-final-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 767px) {
  .tz-final-container,
  .tz-final-header-inner {
    width: calc(100% - 22px);

    margin-left: 11px;
    margin-right: 11px;
  }

  .tz-final-header-inner {
    min-height: 62px;
  }

  .tz-final-logo {
    width: 31px;
    height: 31px;
  }

  .tz-final-logo img {
    width: 21px;
    height: 21px;
  }

  .tz-final-wordmark strong {
    font-size: 14px;
  }

  .tz-final-wordmark span {
    font-size: 8px;
  }

  .tz-final-actions > a:first-child {
    display: none;
  }

  .tz-final-register {
    min-height: 33px;

    padding: 0 10px;

    font-size: 8px;
  }

  .tz-final-hero-grid {
    min-height: auto;

    padding: 45px 0 48px;

    gap: 37px;
  }

  .tz-final-hero-copy h1 {
    font-size: clamp(40px, 12vw, 57px) !important;
  }

  .tz-final-hero-copy > p {
    margin-top: 18px !important;

    font-size: 13px !important;
  }

  .tz-final-hero-buttons {
    align-items: stretch;

    flex-direction: column;

    gap: 13px;

    margin-top: 24px;
  }

  .tz-final-main-button {
    width: 100%;
  }

  .tz-final-text-button {
    width: max-content;
  }

  .tz-final-market-head {
    min-height: 64px;

    padding: 0 13px;
  }

  .tz-final-search {
    margin: 11px;
  }

  .tz-final-tabs {
    padding: 0 11px 11px;
  }

  .tz-final-product-row {
    min-height: 70px;

    grid-template-columns:
      23px
      37px
      minmax(0, 1fr)
      14px;

    gap: 8px;

    padding: 0 11px;
  }

  .tz-final-product-icon {
    width: 37px;
    height: 37px;
  }

  .tz-final-market-foot span:nth-child(2) {
    display: none;
  }

  .tz-final-discovery-inner {
    min-height: 56px;

    gap: 19px;
  }

  .tz-final-discovery-all {
    margin-left: 0;
  }

  .tz-final-section {
    padding: 60px 0;
  }

  .tz-final-section-head {
    align-items: flex-start;

    flex-direction: column;

    gap: 12px;
  }

  .tz-final-section-head h2 {
    font-size: 29px;
  }

  .tz-final-product-grid {
    grid-template-columns: 1fr;
  }

  .tz-final-product-cover {
    height: 230px;
  }

  .tz-final-ecosystem {
    padding: 60px 0;
  }

  .tz-final-ecosystem-head h2 {
    font-size: 29px;
  }

  .tz-final-role-grid {
    grid-template-columns: 1fr;
  }

  .tz-final-role {
    min-height: 220px;
  }

  .tz-final-role > small {
    margin-top: 25px;
  }

  .tz-final-cta {
    padding: 65px 0;
  }

  .tz-final-cta-inner {
    align-items: flex-start;

    flex-direction: column;

    gap: 35px;
  }

  .tz-final-cta h2 {
    font-size: 35px;
  }

  .tz-final-cta-links {
    width: 100%;
  }

  .tz-final-footer-main {
    min-height: auto;

    grid-template-columns: repeat(2, minmax(0, 1fr));

    gap: 30px 20px;

    padding: 30px 0;
  }

  .tz-final-footer-about {
    grid-column: 1 / -1;
  }

  .tz-final-footer-bottom {
    min-height: 65px;

    align-items: flex-start;

    justify-content: center;

    flex-direction: column;

    gap: 4px;
  }

  .tz-final-footer-bottom span:last-child {
    display: none;
  }
}
/* ============================================================
   TZ GLOBAL COMMERCE THEME
   ============================================================ */

:root {
  --tz-bg: #10100f;
  --tz-surface: #171615;
  --tz-surface-2: #1e1c1a;
  --tz-surface-3: #25221f;

  --tz-line: #2d2926;
  --tz-line-strong: #3a3531;

  --tz-text: #f0ece5;
  --tz-text-2: #d8d2ca;

  --tz-muted: #96908a;
  --tz-muted-2: #67615c;

  --tz-brand: #b04a3a;
  --tz-brand-hover: #c45f4d;
  --tz-brand-soft: rgba(176, 74, 58, 0.11);

  --bg: #10100f !important;
  --panel: #171615 !important;
  --panel-2: #1e1c1a !important;
  --panel-3: #25221f !important;

  --line: #2d2926 !important;
  --line-strong: #3a3531 !important;

  --text: #f0ece5 !important;
  --text-2: #d8d2ca !important;
  --muted: #96908a !important;
  --muted-2: #67615c !important;

  --blue: #b04a3a !important;
  --blue-strong: #c45f4d !important;
  --blue-soft: rgba(176, 74, 58, 0.11) !important;

  --brand: #b04a3a !important;
  --brand-hover: #c45f4d !important;
}

/* ============================================================
   GLOBAL SURFACES
   ============================================================ */

html {
  background: var(--tz-bg) !important;
  color-scheme: dark !important;
}

body {
  background: var(--tz-bg) !important;
  color: var(--tz-text) !important;
}

.page,
.home-page,
.home-v3,
.tz-home-v4,
.dashboard-shell,
.dashboard-main {
  background: var(--tz-bg) !important;
  color: var(--tz-text) !important;
}

/* ============================================================
   GLOBAL HEADERS
   ============================================================ */

.site-header,
.topbar,
.checkout-header,
.dashboard-topbar,
.dashboard-sidebar,
.dashboard-sidebar-top,
.dashboard-sidebar-bottom {
  background: #0d0d0c !important;
  border-color: var(--tz-line) !important;
}

/* ============================================================
   GLOBAL TEXT
   ============================================================ */

h1,
h2,
h3,
h4,
h5,
h6,
strong,
.section-title,
.dashboard-page-head h1,
.product-title,
.product-buy h2,
.checkout-heading h1 {
  color: var(--tz-text) !important;
}

p,
.lead,
.section-subtitle,
.product-description,
.product-detail-description,
.checkout-heading p {
  color: var(--tz-muted) !important;
}

/* ============================================================
   GLOBAL ACTIONS
   ============================================================ */

.btn-primary,
.shell-btn-primary,
.button,
.checkout-submit,
.home-v3-primary,
.tz-v4-action-main {
  color: #fff9f6 !important;
  background: var(--tz-brand) !important;
  border-color: var(--tz-brand) !important;
}

.btn-primary:hover,
.shell-btn-primary:hover,
.button:hover,
.checkout-submit:hover,
.home-v3-primary:hover,
.tz-v4-action-main:hover {
  background: var(--tz-brand-hover) !important;
  border-color: var(--tz-brand-hover) !important;
}

.btn-secondary,
.shell-btn-secondary {
  color: var(--tz-text-2) !important;
  background: var(--tz-surface) !important;
  border-color: var(--tz-line-strong) !important;
}

.btn-secondary:hover,
.shell-btn-secondary:hover {
  background: var(--tz-surface-2) !important;
}

/* ============================================================
   GLOBAL INPUTS
   ============================================================ */

input,
textarea,
select,
.input,
.textarea,
.select,
.section-search,
.dashboard-search {
  color: var(--tz-text) !important;
  background: #0d0d0c !important;
  border-color: var(--tz-line) !important;
}

input::placeholder,
textarea::placeholder,
.input::placeholder,
.textarea::placeholder {
  color: var(--tz-muted-2) !important;
}

input:focus,
textarea:focus,
select:focus,
.input:focus,
.textarea:focus,
.select:focus,
.section-search:focus-within,
.dashboard-search:focus-within {
  border-color: rgba(176, 74, 58, 0.62) !important;

  box-shadow: 0 0 0 3px rgba(176, 74, 58, 0.08) !important;
}

/* ============================================================
   GLOBAL PANELS
   ============================================================ */

.card,
.section-table,
.section-empty,
.section-form-panel,
.product-buy,
.checkout-summary,
.home-v3-showcase,
.tz-v4-hero-side {
  color: var(--tz-text) !important;

  background: var(--tz-surface) !important;

  border-color: var(--tz-line) !important;

  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.23) !important;
}

/* ============================================================
   DASHBOARD
   ============================================================ */

.dashboard-nav-item {
  color: #827b75 !important;
}

.dashboard-nav-item:hover {
  color: var(--tz-text) !important;
  background: var(--tz-surface) !important;
}

.dashboard-nav-item-active {
  color: #f0d8d3 !important;

  background: #211716 !important;

  box-shadow: inset 2px 0 0 var(--tz-brand) !important;
}

.dashboard-avatar {
  background: #2a1b18 !important;
  border-color: #59332c !important;
  color: #e0a69a !important;
}

.dashboard-icon-button:hover {
  color: var(--tz-brand-hover) !important;
  background: var(--tz-surface) !important;
}

/* ============================================================
   PRODUCT / CHECKOUT
   ============================================================ */

.product-buy,
.checkout-summary {
  background: var(--tz-surface) !important;
  border-color: var(--tz-line) !important;
}

.product-buy-status,
.checkout-method-active {
  color: #7fc295 !important;
}

.product-divider,
.product-buy-line,
.checkout-summary-line,
.checkout-summary-total {
  border-color: var(--tz-line) !important;
}

.checkout-method {
  background: #0d0d0c !important;
  border-color: var(--tz-line) !important;
}

/* ============================================================
   TABLES
   ============================================================ */

.section-table-head {
  background: #0d0d0c !important;
  border-color: var(--tz-line) !important;
}

.section-table-row {
  border-color: var(--tz-line) !important;
}

.section-table-row:hover {
  background: var(--tz-surface-2) !important;
}

.section-status-success {
  color: #7fc295 !important;
}

.section-status-warning {
  color: #d0ad6a !important;
}

.section-status-danger {
  color: #d47c75 !important;
}

.section-more:hover {
  color: var(--tz-brand-hover) !important;
  background: #211716 !important;
  border-color: #59332c !important;
}

/* ============================================================
   OLD HOME / SUPPORT CLASSES
   ============================================================ */

.tz-v4-hero,
.home-v3-hero {
  background: var(--tz-bg) !important;
}

.tz-v4-discovery-bar,
.tz-v4-intro,
.tz-v4-people,
.home-v3-intro,
.home-v3-benefit-strip {
  background: var(--tz-surface) !important;
  border-color: var(--tz-line) !important;
}

.tz-v4-final,
.home-v3-final {
  background: #15110f !important;
}

.tz-v4-live-cover,
.home-v3-product-mark,
.checkout-product-mark {
  background: linear-gradient(145deg, #34211e, #171210) !important;

  border-color: #5a342d !important;

