.page-transition {
  position: relative;
  isolation: isolate;
  animation: tzPageEnter .62s cubic-bezier(.16,1,.3,1) both;
}

.page-transition::before {
  content: "";
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  z-index: 9999;
  pointer-events: none;
  background: #7f2637;
  transform-origin: top;
  animation: tzAccentReveal .62s cubic-bezier(.16,1,.3,1) both;
}

.page-transition::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    rgba(127,38,55,.12),
    transparent 22%,
    transparent 78%,
    rgba(127,38,55,.05)
  );
  opacity: 0;
  animation: tzAmbient .62s ease-out both;
}

@keyframes tzPageEnter {
  from {
    opacity: 0;
    transform: translateX(10px);
    filter: blur(2px);
  }

  55% {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }

  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes tzAccentReveal {
  from {
    transform: scaleY(0);
    opacity: 0;
  }

  18% {
    opacity: 1;
  }

  70% {
    transform: scaleY(1);
    opacity: 1;
  }

  to {
    transform: scaleY(0);
    opacity: 0;
  }
}

@keyframes tzAmbient {
  0% {
    opacity: 0;
  }

  20% {
    opacity: 1;
  }

  65% {
    opacity: .35;
  }

  100% {
    opacity: 0;
  }
}


