/* =========================================================
   TZ STORE � TRANSI��O SIGNATURE
   ========================================================= */

.page-transition {
  position: relative !important;
  isolation: isolate;
  animation: tzSignatureEnter .65s cubic-bezier(.16,1,.3,1) both !important;
}

/* remove efeitos anteriores */
.page-transition::before {
  content: "" !important;
  position: fixed !important;
  left: 50% !important;
  top: 50% !important;
  width: 24px !important;
  height: 24px !important;
  z-index: 9999 !important;
  pointer-events: none !important;
  border: 1px solid rgba(127,38,55,.85) !important;
  border-radius: 50% !important;
  background: transparent !important;
  box-shadow:
    0 0 0 1px rgba(127,38,55,.08),
    0 0 26px rgba(127,38,55,.18) !important;
  transform: translate(-50%,-50%) scale(0) !important;
  opacity: 0 !important;
  animation: tzSignatureRing .72s cubic-bezier(.16,1,.3,1) both !important;
}

.page-transition::after {
  content: "" !important;
  position: fixed !important;
  inset: 0 !important;
  z-index: 9998 !important;
  pointer-events: none !important;
  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(127,38,55,.10),
      transparent 18%
    ) !important;
  opacity: 0 !important;
  animation: tzSignatureGlow .72s ease-out both !important;
}

@keyframes tzSignatureRing {
  0% {
    transform: translate(-50%,-50%) scale(0);
    opacity: 0;
  }

  12% {
    opacity: 1;
  }

  55% {
    transform: translate(-50%,-50%) scale(18);
    opacity: .65;
  }

  100% {
    transform: translate(-50%,-50%) scale(52);
    opacity: 0;
  }
}

@keyframes tzSignatureGlow {
  0% {
    opacity: 0;
    transform: scale(.96);
  }

  25% {
    opacity: 1;
  }

  65% {
    opacity: .28;
    transform: scale(1);
  }

  100% {
    opacity: 0;
    transform: scale(1.015);
  }
}

@keyframes tzSignatureEnter {
  0% {
    opacity: 0;
    transform:
      translateY(12px)
      scale(.985);
    filter: blur(3px);
  }

  55% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
    filter: blur(0);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
    filter: blur(0);
  }
}


